problems.stem:
写出下面程序的运行结果（一行，整数之间用一个空格分隔）。
```
#include <stdio.h>

#define MAXV 20

int main(void)
{
    int a[MAXV][MAXV], n, m, i, j, u, v, d;

    if (scanf("%d %d", &n, &m) != 2)
        return 1;
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            a[i][j] = 0;
    for (i = 0; i < m; i++)          /* 无向图：读入一条边就在对称位置各置 1 */
    {
        if (scanf("%d %d", &u, &v) != 2)
            return 1;
        a[u][v] = 1;
        a[v][u] = 1;
    }
    for (i = 0; i < n; i++)          /* 逐行统计 1 的个数，即该顶点的度 */
    {
        d = 0;
        for (j = 0; j < n; j++)
            if (a[i][j] != 0)
                d++;
        printf("%d%c", d, i == n - 1 ? '\n' : ' ');
    }

    return 0;
}
```
运行时输入：
```
5 5
0 1
0 2
1 2
2 3
3 4
```

