#include <stdio.h>
#include <stdlib.h>

typedef struct ArcNode
{
    int adjvex;
    struct ArcNode *nextarc;
} ArcNode;

typedef struct
{
    ArcNode *firstarc;
} VNode;

static ArcNode *New(int v, ArcNode *nx)   /* 造一个边表结点并接到 nx 之前 */
{
    ArcNode *p = (ArcNode *)malloc(sizeof(ArcNode));

    p->adjvex = v;
    p->nextarc = nx;
    return p;
}

