{
    VNode G[4];
    ArcNode *p;
    int i, d;

    G[0].firstarc = New(3, New(1, NULL));
    G[1].firstarc = New(0, NULL);
    G[2].firstarc = New(3, New(1, New(0, NULL)));
    G[3].firstarc = New(2, NULL);
    for (i = 0; i < 4; i++)
    {
        d = 0;
        for (p = G[i].firstarc; p != NULL; p = p->nextarc)
            d++;
        printf("%d:%d%c", i, d, i == 3 ? '\n' : ' ');
    }

    return 0;
}
