#include <stdio.h>
#include <stdlib.h>

#define MAXV 20

typedef struct ArcNode
{
    int adjvex;
    struct ArcNode *nextarc;
} ArcNode;

typedef struct
{
    ArcNode *firstarc;
} VNode;

static VNode G[MAXV];

void InsertArc(int u, int v)        /* 头插法把弧 <u,v> 插入第 u 条链表 */
{
    ArcNode *p = (ArcNode *)malloc(sizeof(ArcNode));

    p->adjvex = v;
    p->nextarc = G[u].firstarc;
    G[u].firstarc = p;
}

int main(void)
{
    int n, m, i, u, v;
    ArcNode *p;

    if (scanf("%d %d", &n, &m) != 2)
        return 1;
    for (i = 0; i < n; i++)
        G[i].firstarc = NULL;
    for (i = 0; i < m; i++)
    {
        if (scanf("%d %d", &u, &v) != 2)
            return 1;
        InsertArc(u, v);            /* 无向图：两个方向都要插 */
        InsertArc(v, u);
    }
    for (i = 0; i < n; i++)
    {
        printf("%d:", i);
        for (p = G[i].firstarc; p != NULL; p = p->nextarc)
            printf(" %d", p->adjvex);
        printf("\n");
    }

    return 0;
}

