#include <stdio.h>

#define MAXV 50

static int A[MAXV][MAXV];

int main(void)
{
    int n, m, i, j, u, v;

    if (scanf("%d %d", &n, &m) != 2)
        return 1;
    for (i = 0; i < m; i++)
    {
        if (scanf("%d %d", &u, &v) != 2)
            return 1;
        if (u == v)
            continue;               /* 自环不计入邻接表 */
        A[u][v] = 1;                /* 矩阵天然完成重复边去重 */
        A[v][u] = 1;
    }
    for (i = 0; i < n; i++)
    {
        printf("%d:", i);
        for (j = 0; j < n; j++)
            if (A[i][j] != 0)
                printf(" %d", j);
        printf("\n");
    }

    return 0;
}

