#include <stdio.h>

#define MAXV 50

static int A[MAXV][MAXV];

int main(void)
{
    int n, m, i, j, u, v, od, id, best = 0, bestod = -1;

    if (scanf("%d %d", &n, &m) != 2)
        return 1;
    for (i = 0; i < m; i++)
    {
        if (scanf("%d %d", &u, &v) != 2)
            return 1;
        A[u][v] = 1;
    }
    for (i = 0; i < n; i++)         /* 第 1 行：出度，扫行 */
    {
        od = 0;
        for (j = 0; j < n; j++)
            if (A[i][j] != 0)
                od++;
        printf("%d%c", od, i == n - 1 ? '\n' : ' ');
    }
    for (i = 0; i < n; i++)         /* 第 2 行：入度，扫列 */
    {
        id = 0;
        for (j = 0; j < n; j++)
            if (A[j][i] != 0)
                id++;
        printf("%d%c", id, i == n - 1 ? '\n' : ' ');
    }
    for (i = 0; i < n; i++)         /* 第 3 行：出度最大的顶点，严格大于才更新，故并列取最小编号 */
    {
        od = 0;
        for (j = 0; j < n; j++)
            if (A[i][j] != 0)
                od++;
        if (od > bestod)
        {
            bestod = od;
            best = i;
        }
    }
    printf("%d %d\n", best, bestod);

    return 0;
}

