写出下列程序段的时间复杂度（用大 O 表示）。
```
void DFS(int v)                 /* 邻接矩阵存储，n 为顶点数 */
{
    int w;

    visited[v] = 1;
    for (w = 0; w < n; w++)     /* 扫描第 v 行找一个未访问的邻接点 */
        if (A[v][w] == 1 && visited[w] == 0)
            DFS(w);
}
