{
    while (parent[x] != x)
        x = parent[x];
    return x;
}

int Cmp(const void *a, const void *b)
{
    const Edge *p = (const Edge *)a;
    const Edge *q = (const Edge *)b;

    if (p->w != q->w)
        return p->w - q->w;
    if (p->u != q->u)
        return p->u - q->u;
    return p->v - q->v;
}

int main(void)
{
    int n, m, i, cnt = 0, total = 0, ru, rv;

