#include <stdio.h>

#define MAXV 30
#define INF 1000000

static int A[MAXV][MAXV];
static int dist[MAXV];
static int S[MAXV];               /* S[j]=1 表示 j 的最短距离已确定 */
static int path[MAXV];
static int n;

void Dijkstra(int v0)
{
    int i, j, u, min;

    for (i = 0; i < n; i++)
    {
        dist[i] = /*__BLANK_1__*/;
        S[i] = 0;
        path[i] = (A[v0][i] < INF) ? v0 : -1;
    }
    dist[v0] = 0;
    S[v0] = 1;
    for (i = 1; i < n; i++)       /* 再确定 n-1 个顶点 */
    {
        min = INF;
        u = -1;
        for (j = 0; j < n; j++)
            if (/*__BLANK_2__*/)
            {
                min = dist[j];
                u = j;
            }
        if (u < 0)
            break;                /* 剩下的顶点都不可达 */
        /*__BLANK_3__*/;                    /* u 并入 S，其最短距离已确定 */
        for (j = 0; j < n; j++)   /* 用 u 松弛其余顶点 */
            if (S[j] == 0 && A[u][j] < INF && /*__BLANK_4__*/)
            {
                dist[j] = min + A[u][j];
                path[j] = u;
            }
    }
    for (i = 0; i < n; i++)
        printf("%d%c", dist[i] >= INF ? -1 : dist[i], i == n - 1 ? '\n' : ' ');
}

int main(void)
{
    int m, s, i, j, u, v, w;

    if (scanf("%d %d %d", &n, &m, &s) != 3)
        return 1;
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            A[i][j] = (i == j) ? 0 : INF;
    for (i = 0; i < m; i++)
