problems.stem:
程序用邻接矩阵存储有向图，实现基于栈的拓扑排序：先把所有入度为 0 的顶点压入栈（入栈后把入度置 -1 作标记），随后不断弹栈、输出顶点、把其后继顶点的入度减 1，入度归零者继续入栈。请补全 4 处空白。输入：第 1 行 n m，随后 m 行每行一条弧 u v（顶点 0 开始，可能有重弧）。输出：第 1 行是拓扑序列（整数间一个空格），第 2 行是 OK（无回路）或 HAS CYCLE（有回路）。
```
#include <stdio.h>

#define MAXV 30

static int A[MAXV][MAXV];
static int indeg[MAXV];
static int st[MAXV];              /* 暂存入度为 0 的顶点，用栈实现 */
static int n;

int TopoSort(void)                /* 成功返回 1，图中有回路返回 0 */
{
    int top = -1, i, j, v, cnt = 0;

    for (i = 0; i < n; i++)
        if (/*__BLANK_1__*/)
        {
            st[++top] = i;
            indeg[i] = -1;        /* 置 -1 表示已入栈，避免重复入栈 */
        }
    while (top >= 0)
    {
        v = st[top--];
        printf("%d ", v);
        cnt++;
        for (j = 0; j < n; j++)
            if (/*__BLANK_2__*/)
            {
                /*__BLANK_3__*/;            /* 删去弧 <v,j>，j 的入度减 1 */
                if (indeg[j] == 0)
                {
                    st[++top] = j;
                    indeg[j] = -1;
                }
            }
    }
    if (/*__BLANK_4__*/)
        return 0;                 /* 输出顶点数不足 n，说明存在回路 */
    return 1;
}

int main(void)
{
    int m, i, j, u, v, ok;

    if (scanf("%d %d", &n, &m) != 2)
        return 1;
    for (i = 0; i < n; i++)
    {
        indeg[i] = 0;
        for (j = 0; j < n; j++)
            A[i][j] = 0;
    }
    for (i = 0; i < m; i++)
    {
        if (scanf("%d %d", &u, &v) != 2)
            return 1;
        if (A[u][v] == 0)         /* 重弧只累加一次入度 */
        {
            A[u][v] = 1;
            indeg[v]++;
        }
    }
    ok = TopoSort();
    printf("\n%s\n", ok ? "OK" : "HAS CYCLE");

    return 0;
}
