static int A[MAXV][MAXV];
static int indeg[MAXV];
static int qu[MAXV];
static int order[MAXV];

int main(void)
{
    int n, m, i, j, u, v, front = 0, rear = 0, cnt = 0;

    if (scanf("%d %d", &n, &m) != 2)
        return 1;
    for (i = 0; i < m; i++)
    {
        if (scanf("%d %d", &u, &v) != 2)
            return 1;
        if (A[u][v] == 0)         /* 重弧只累加一次入度 */
        {
            A[u][v] = 1;
            indeg[v]++;
        }
    }
    for (i = 0; i < n; i++)
        if (indeg[i] == 0)
            qu[rear++] = i;       /* 按编号升序扫描，天然满足入队次序要求 */
    while (front < rear)
    {
        v = qu[front++];
        order[cnt++] = v;
        for (j = 0; j < n; j++)
            if (A[v][j] != 0)
            {
                indeg[j]--;
                if (indeg[j] == 0)
                    qu[rear++] = j;
            }
    }
    for (i = 0; i < cnt; i++)
        printf("%d%c", order[i], i == cnt - 1 ? '\n' : ' ');
    if (cnt == 0)
        printf("NONE\n");
    printf("%s\n", cnt == n ? "OK" : "CYCLE");

    return 0;
}

